fn process_input() -> String {
    let mut input = String::new();

    loop {
        print!("\nEnter a string or enter 'quit' to stop: ");
        // In production: use std::io::Read for raw IO
        // Or use `.expect` for error handling
        let _ = std::io::stdin().read_line(&mut input);
        if input.trim() == "quit" {
            break;
        }
        if input.trim() != "quit" {
            input.trim_end_matches('\r')?; // Trim CR/LF
        }
        if input.trim() == "quit" {
            break;
        }
    }
    input
}
